{
  render: (args: InformerHintStoryArgs) => ({
    components: {
      InformerHint
    },
    setup() {
      const visibleModel = ref(args.visible);
      watch(() => args.visible, visible => {
        visibleModel.value = visible;
      });
      return {
        args,
        visibleModel
      };
    },
    template: `
      <div style="${canvasStyle}">
        <div style="${informerAreaStyle}">
          <div style="${cardStyle}">
            <strong style="${titleStyle}">Обновили onboarding компании</strong>
            <p style="${textStyle}">
              Вариант со slot показывает, как компонент можно использовать не только с дефолтным i18n-текстом.
            </p>
          </div>

          <InformerHint
            :button-style="args.buttonStyle"
            :hint-width="args.hintWidth"
            :offset="args.offset"
            :visible="visibleModel"
            @close="args.close?.()"
            @update:visible="visibleModel = $event; args['update:visible']?.($event)"
          >
            <div style="display: grid; gap: 4px;">
              <h3 style="margin: 0; font-size: 15px; font-weight: 700; line-height: 20px;">
                Редактирование стало быстрее
              </h3>
              <p style="margin: 0; font-size: 14px; line-height: 20px;">
                Собрали основные действия в одном месте, чтобы важные настройки были под рукой.
              </p>
            </div>
          </InformerHint>
        </div>
      </div>
    `
  })
}

